CREATE FUNCTION public.gridex_normalize_customer_number_prefix(p_value text, p_fallback_name text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_prefix text;
  v_words text[];
  v_word text;
  v_initials text := '';
begin
  v_prefix := upper(regexp_replace(coalesce(nullif(p_value, ''), ''), '[^A-Za-z0-9]', '', 'g'));

  if v_prefix = '' and coalesce(nullif(p_fallback_name, ''), '') <> '' then
    v_words := array(
      select word
      from regexp_split_to_table(
        upper(regexp_replace(p_fallback_name, '[^A-Za-z0-9ÅÄÖåäö]+', ' ', 'g')),
        '\s+'
      ) as word
      where word <> ''
        and word not in ('AB','HB','KB','EF','LTD','LLC','INC','OY','ASA','AS','ENERGI','ELHANDEL','EL','ENERGY','POWER')
      limit 6
    );

    if array_length(v_words, 1) >= 2 then
      foreach v_word in array v_words loop
        v_initials := v_initials || left(v_word, 1);
      end loop;
      v_prefix := v_initials;
    elsif array_length(v_words, 1) = 1 then
      v_prefix := left(regexp_replace(v_words[1], '[^A-Z0-9]', '', 'g'), 6);
    else
      v_prefix := left(upper(regexp_replace(p_fallback_name, '[^A-Za-z0-9]', '', 'g')), 6);
    end if;
  end if;

  v_prefix := coalesce(nullif(v_prefix, ''), 'GDX');
  if length(v_prefix) < 2 then
    v_prefix := rpad(v_prefix, 2, 'X');
  end if;

  return left(v_prefix, 12);
end;
$$;

CREATE FUNCTION public.gridex_default_customer_number_prefix(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
begin
  select public.gridex_normalize_customer_number_prefix(
           coalesce(
             nullif(c.customer_number_prefix, ''),
             nullif(s.prefix, ''),
             c.metadata->>'customer_number_prefix'
           ),
           coalesce(nullif(c.slug, ''), nullif(c.name, ''), 'GDX')
         )
    into v_prefix
  from public.companies c
  left join public.company_customer_number_sequences s on s.company_id = c.id
  where c.id = p_company_id;

  return coalesce(v_prefix, 'GDX');
end;
$$;

CREATE FUNCTION public.gridex_next_customer_number(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_prefix text;
  v_existing_next bigint;
  v_number bigint;
begin
  if p_company_id is null then
    raise exception 'company_id is required';
  end if;

  v_prefix := public.gridex_default_customer_number_prefix(p_company_id);

  if v_prefix !~ '^[A-Z0-9]{2,12}$' then
    raise exception 'invalid customer number prefix: %', v_prefix;
  end if;

  select coalesce(max(nullif(substring(customer_number from '([0-9]+)$'), '')::bigint) + 1, 100001)
    into v_existing_next
  from public.customers
  where company_id = p_company_id
    and customer_number is not null;

  insert into public.company_customer_number_sequences(company_id, prefix, next_number)
  values (p_company_id, v_prefix, v_existing_next)
  on conflict (company_id) do nothing;

  update public.company_customer_number_sequences
     set next_number = greatest(next_number, v_existing_next) + 1,
         prefix = v_prefix,
         updated_at = now()
   where company_id = p_company_id
   returning prefix, next_number - 1 into v_prefix, v_number;

  if v_number is null then
    raise exception 'customer number sequence could not be reserved';
  end if;

  return v_prefix || '-' || v_number::text;
end;
$_$;

CREATE FUNCTION public.gridex_db4b_archive_customer_registry_row(p_lookup text, p_email text DEFAULT NULL::text, p_apply boolean DEFAULT false, p_reason text DEFAULT 'Archived old/test customer from active customer registry.'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_customer_count integer := 0;
  v_updated_customers integer := 0;
begin
  if nullif(btrim(coalesce(p_lookup, '')), '') is null
     and nullif(btrim(coalesce(p_email, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'p_lookup or p_email is required';
  end if;

  select count(*) into v_customer_count
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  if not p_apply then
    return jsonb_build_object(
      'apply', false,
      'matched_customers', v_customer_count,
      'matched_customer_profiles', 0,
      'message', 'Dry-run only. Re-run with p_apply=true to archive matching canonical customer rows.'
    );
  end if;

  insert into public.gridex_archived_customer_registry_rows(
    archived_by, archive_reason, source_table, source_id, source_email, source_row
  )
  select
    v_actor, p_reason, 'customers', customer.id::text, customer.email,
    to_jsonb(customer)
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  update public.customers customer
  set status = 'archived',
      metadata = coalesce(customer.metadata, '{}'::jsonb) || jsonb_build_object(
        'archived_from_active_registry', true,
        'archived_at', now(),
        'archived_reason', p_reason,
        'db4b_cleanup', true
      ),
      updated_at = now(),
      updated_by = coalesce(v_actor, customer.updated_by)
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );
  get diagnostics v_updated_customers = row_count;

  return jsonb_build_object(
    'apply', true,
    'matched_customers_before_apply', v_customer_count,
    'matched_customer_profiles_before_apply', 0,
    'archived_customers', v_updated_customers,
    'removed_customer_profiles', 0,
    'message', 'Matching canonical customer rows were archived. Authentication and tenant memberships were not touched.'
  );
end
$$;
